1	import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';
2	import { workflowFiles } from '../../../shared/engine/checks/helpers/github-workflows.mjs';
3	
4	// WHY. Node's default test discovery skips dot-directories outright, and every
5	// test this repo has lives under `.claudinite/`. So a `node --test` that names
6	// no path finds nothing, reports success, and reads exactly like a passing
7	// suite — the failure mode is a green tick over zero assertions, which no
8	// human and no CI log inspection reliably catches.
9	//
10	// The same silent-green also arrives one step later: an invocation that DOES
11	// name a path, but whose glob or directory matches no file in the tree (a typo,
12	// a moved fixture, a pack renamed). That is why this rule asserts the stronger
13	// property — the invocation's arguments must resolve to something that exists —
14	// rather than merely "an argument was passed". Watching the run go green is
15	// never the confirmation; a statically non-empty argument set is.
16	//
17	// SCOPE. The command surfaces a run can be spelled on: `package.json` scripts
18	// (the local invocation) and `.github/workflows/*.yml` (the CI step). A command
19	// carrying shell interpolation (`$…`, backticks) is not judged — its arguments
20	// are not knowable from the artifact, and a check that guesses cries wolf.
21	
22	const SHARED_PREFIX = '.claudinite/shared/';
23	
24	// A shell command's tokens, quotes stripped. Deliberately naive: the commands
25	// this rule reads are short literal invocations, and anything with substitution
26	// in it is skipped before we get here.
27	function tokenize(command) {
28	  return command.trim().split(/\s+/).filter(Boolean).map((t) => t.replace(/^['"]|['"]$/g, ''));
29	}
30	
31	// Split a script body / run: line into individual commands on the shell's
32	// separators, so `npm ci && node --test` is judged as its two commands.
33	function commands(text) {
34	  return text.split(/\n|&&|\|\||[;|]/g);
35	}
36	
37	// A glob token as a regex over '/'-separated repo paths: `**` crosses
38	// directories, `*` and `?` do not.
39	function globToRegExp(pattern) {
40	  let out = '';
41	  for (let i = 0; i < pattern.length; i += 1) {
42	    const c = pattern[i];
43	    if (c === '*') {
44	      if (pattern[i + 1] === '*') {
45	        // `**/` may match zero directories, so the following slash is optional.
46	        i += 1;
47	        if (pattern[i + 1] === '/') { i += 1; out += '(?:.*/)?'; } else out += '.*';
48	      } else out += '[^/]*';
49	    } else if (c === '?') out += '[^/]';
50	    else out += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
51	  }
52	  return new RegExp(`^${out}$`);
53	}
54	
55	// Does this argument name at least one file that exists in the repo — as a
56	// glob, an exact path, or a directory holding files?
57	export function resolvesToFiles(arg, paths) {
58	  if (!arg) return false;
59	  if (/[*?[\]]/.test(arg)) {
60	    const re = globToRegExp(arg);
61	    return paths.some((p) => re.test(p));
62	  }
63	  const clean = arg.replace(/\/+$/, '');
64	  return paths.some((p) => p === clean || p.startsWith(`${clean}/`));
65	}
66	
67	// The invocations of `node --test` in one command string, and whether each
68	// one's arguments resolve. Exported for the fixture.
69	export function judgeCommand(command, paths) {
70	  if (/[$`]/.test(command)) return null; // interpolated — not knowable from the artifact
71	  const tokens = tokenize(command);
72	  const nodeAt = tokens.findIndex((t) => t === 'node' || t.endsWith('/node'));
73	  if (nodeAt < 0) return null;
74	  const args = tokens.slice(nodeAt + 1);
75	  if (!args.includes('--test')) return null;
76	  // Flags are skipped; every other token is a candidate path. A flag's separate
77	  // value can only ever make the rule quieter, never noisier.
78	  const positional = args.filter((t) => !t.startsWith('-'));
79	  return { ok: positional.some((a) => resolvesToFiles(a, paths)) };
80	}
81	
82	const rule = {
83	  id: 'claudinite-website/node-test-discovery',
84	  severity: 'blocking',
85	  description: 'A `node --test` invocation must name test paths that exist — default discovery skips this repo\'s dot-directories',
86	  doc: '.claudinite/local/packs/claudinite-website/RULES.md',
87	  why: "Node's test discovery ignores dot-directories, and every test here lives under `.claudinite/` — an invocation that names no existing path runs zero tests and exits green, which is indistinguishable from a passing suite",
88	
89	  run(ctx) {
90	    // Tracked ∪ scanned: `ctx.tracked` is the whole tree in either mode, and
91	    // `ctx.files` adds the not-yet-committed ones — a test file added in the
92	    // same change as the step that runs it must resolve, or the rule fires on
93	    // the very commit that fixes it.
94	    const paths = [...new Set([...ctx.tracked, ...(ctx.files || [])])]
95	      .filter((f) => !f.startsWith(SHARED_PREFIX));
96	    const out = [];
97	
98	    const report = (file, line, command) => out.push(finding(rule, {
99	      file,
100	      line,
101	      what: `\`${command.trim()}\` names no test path that exists in the tree, so it discovers nothing and exits green`,
102	      fix: "pass an explicit path or glob for the tests, e.g. `node --test '.claudinite/local/packs/**/*.test.mjs'`, and confirm the run's test count is non-zero",
103	    }));
104	
105	    const pkg = ctx.read('package.json');
106	    if (pkg !== null) {
107	      let scripts = {};
108	      try { scripts = JSON.parse(pkg).scripts || {}; } catch { scripts = {}; }
109	      const lines = pkg.split('\n');
110	      for (const [name, body] of Object.entries(scripts)) {
111	        if (typeof body !== 'string') continue;
112	        for (const command of commands(body)) {
113	          const verdict = judgeCommand(command, paths);
114	          if (verdict && !verdict.ok) {
115	            const at = lines.findIndex((l) => l.includes(`"${name}":`));
116	            report('package.json', at < 0 ? null : at + 1, command);
117	          }
118	        }
119	      }
120	    }
121	
122	    for (const wf of workflowFiles(ctx)) {
123	      const text = ctx.read(wf);
124	      if (text === null) continue;
125	      const lines = text.split('\n');
126	      for (let i = 0; i < lines.length; i += 1) {
127	        for (const command of commands(lines[i])) {
128	          const verdict = judgeCommand(command, paths);
129	          if (verdict && !verdict.ok) report(wf, i + 1, command);
130	        }
131	      }
132	    }
133	
134	    return out;
135	  },
136	};
137	
138	export default rule;
