1	// Fixture for claudinite-website/node-test-discovery. The bar: a violating
2	// input must produce a finding, a clean one must produce none — proved on the
3	// rule's own `run` against a synthetic context, not on the live repo (whose
4	// content is exactly what the rule is there to keep clean).
5	import { test } from 'node:test';
6	import assert from 'node:assert/strict';
7	import rule from './node-test-discovery.mjs';
8	
9	// The tree the fixture pretends to be: one test file the arguments can resolve
10	// to, plus unrelated content.
11	const TRACKED = [
12	  'package.json',
13	  '.github/workflows/ci.yml',
14	  '.claudinite/local/packs/claudinite-website/node-test-discovery.test.mjs',
15	  '.claudinite/shared/engine/checks/check_the_world.mjs',
16	  'site/index.html',
17	];
18	
19	function ctxWith({ scripts = {}, workflow = null, tracked = TRACKED, untracked = [] }) {
20	  const files = {
21	    'package.json': JSON.stringify({ name: 'fixture', scripts }, null, 2),
22	    ...(workflow === null ? {} : { '.github/workflows/ci.yml': workflow }),
23	  };
24	  return {
25	    tracked,
26	    files: [...tracked, ...untracked],
27	    read: (p) => (p in files ? files[p] : null),
28	  };
29	}
30	
31	const CLEAN_WORKFLOW = `name: CI
32	jobs:
33	  t:
34	    steps:
35	      - run: node --test '.claudinite/local/packs/**/*.test.mjs'
36	`;
37	
38	const BARE_WORKFLOW = `name: CI
39	jobs:
40	  t:
41	    steps:
42	      - run: node --test
43	`;
44	
45	const TYPO_WORKFLOW = `name: CI
46	jobs:
47	  t:
48	    steps:
