52	test('fires on a bare node --test in a workflow step', () => {
53	  const found = rule.run(ctxWith({ workflow: BARE_WORKFLOW }));
54	  assert.equal(found.length, 1);
55	  assert.equal(found[0].rule, 'claudinite-website/node-test-discovery');
56	  assert.equal(found[0].file, '.github/workflows/ci.yml');
57	  assert.equal(found[0].line, 5);
58	  assert.match(found[0].fix, /explicit path or glob/);
59	});
