67	test('fires on a bare node --test in a package.json script', () => {
68	  const found = rule.run(ctxWith({ scripts: { test: 'node --test' } }));
69	  assert.equal(found.length, 1);
70	  assert.equal(found[0].file, 'package.json');
71	  assert.ok(found[0].line > 0);
72	});
73	
74	test('fires when only flags follow --test', () => {
75	  const found = rule.run(ctxWith({ scripts: { test: 'node --test --test-reporter=spec' } }));
76	  assert.equal(found.length, 1);
77	});
78	
79	test('fires on the second command of a chained script', () => {
80	  const found = rule.run(ctxWith({ scripts: { test: 'npm run lint && node --test' } }));
81	  assert.equal(found.length, 1);
82	});
83	
84	test('stays quiet on an invocation whose glob resolves', () => {
85	  assert.deepEqual(rule.run(ctxWith({ workflow: CLEAN_WORKFLOW })), []);
86	});
