97	test('stays quiet on a repo with no node --test at all', () => {
98	  const scripts = { 'bump-version': 'node scripts/bump-version.mjs' };
99	  assert.deepEqual(rule.run(ctxWith({ scripts, workflow: 'name: CI\njobs:\n  c:\n    steps:\n      - run: node .claudinite/shared/engine/checks/check_the_world.mjs\n' })), []);
