+// Comment and markdown furniture, so a claim reads the same in a YAML header,
+// a JS header and a README line.
+function plain(text) {
+  return text
+    .split('\n')
+    .map((l) => l.replace(/^\s*(?:#|\/\/|\*|>|-|\|)+\s?/, '').trim())
+    .join(' ')
+    .replace(/\s+/g, ' ');
