+touches \`site/**\`.
+`;
+
+const README_HONEST = README_CLAIM.replace(' that\ntouches `site/**`.', '.');
+
+function ctxWith({ workflow = UNFILTERED, md = {} }) {
+  const files = { [WORKFLOW]: workflow, ...md };
+  const paths = Object.keys(files);
+  return {
+    files: paths,
+    tracked: paths,
+    read: (p) => (p in files ? files[p] : null),
+  };
